def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, -((bins - remaining) ** 2), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    relative_target = 0.3 * bins
    return np.where(remaining >= 0, -np.exp(((remaining - relative_target) / (bins + 1e-8)) ** 2), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, remaining, -np.inf)
